import { Component, TemplateRef, computed, input, model, output, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { HrmListPage } from '../enterprise-data/hrm-list-page';
import { HrmDataView, HrmDataViewMode } from '../enterprise-data/hrm-data-view';
import { HrmDetailPeek, HrmPeekMode } from '../overlays/hrm-detail-peek';
import { HrmGridColumn } from '../enterprise-data/hrm-grid';
import { HrmCrumb } from '../navigation/hrm-breadcrumb';

type Row = Record<string, unknown>;

/** hrm-list-screen — TEMPLATE màn hình danh sách dữ liệu (dùng như hrm-app-shell:
 *  drop-in, điền input + slot là xong). Ghép sẵn: chrome (breadcrumb/tiêu đề/toolbar/
 *  phân trang qua hrm-list-page) + danh sách 2 chế độ Bảng/Thẻ (hrm-data-view) +
 *  chi tiết đa-surface Side/Center/Full/Tab (hrm-detail-peek). Tự quản bản ghi đang
 *  chọn + trạng thái mở/mode. Toàn token → tự Light/Dark. Đặt trong content hrm-app-shell.
 *
 *  <hrm-list-screen [title]="'Nhân sự'" [columns]="cols" [data]="rows" rowKey="id"
 *     [cardTemplate]="cardTpl" [detailContent]="detailTpl" [detailRoute]="routeFn"
 *     detailTitleField="name" [modeLabels]="labels">
 *     <div lsFilters>…ô tìm/lọc…</div>
 *     <div lsActions><hrm-button>+ Thêm</hrm-button></div>
 *  </hrm-list-screen>
 *  <ng-template #cardTpl let-row>…thẻ…</ng-template>
 *  <ng-template #detailTpl let-row>…chi tiết bản ghi (row)…</ng-template>
 *
 *  detailRoute(row) → url route bản ghi (bắt buộc nếu bật mode full/tab). */
@Component({
  selector: 'hrm-list-screen',
  imports: [NgTemplateOutlet, HrmListPage, HrmDataView, HrmDetailPeek],
  template: `
    <hrm-list-page
      [breadcrumb]="breadcrumb()" [title]="title()" [subtitle]="subtitle()"
      [showBack]="showBack()" (back)="back.emit()"
      [total]="total()" [(pageIndex)]="pageIndex" [(pageSize)]="pageSize" [showSizeChanger]="showSizeChanger()">

      <ng-content select="[lsHeaderActions]" ngProjectAs="[headerActions]" />
      <ng-content select="[lsFilters]" ngProjectAs="[filters]" />
      <ng-content select="[lsActions]" ngProjectAs="[actions]" />
      <ng-content select="[lsPagerInfo]" ngProjectAs="[pagerInfo]" />

      <hrm-data-view
        [columns]="columns()" [data]="data()" [rowKey]="rowKey()"
        [(mode)]="viewMode" [modes]="viewModes()" [cardTemplate]="cardTemplate()"
        [cardMin]="cardMin()" [size]="size()" [selectable]="selectable()"
        [tableLabel]="tableLabel()" [cardLabel]="cardLabel()"
        (openRecord)="onOpen($event)" />
    </hrm-list-page>

    <hrm-detail-peek
      [(open)]="peekOpen" [(peekMode)]="peekMode" [modes]="detailModes()"
      [title]="detailTitle()" [content]="peekBody" [routeUrl]="routeUrl()"
      [width]="detailWidth()" [modalWidth]="detailModalWidth()" [modeLabels]="modeLabels()"
      [switchLabel]="switchLabel()" [expandLabel]="expandLabel()" [closeLabel]="closeLabel()" />

    <!-- Bọc nội dung chi tiết của bên gọi + truyền bản ghi đang chọn qua context $implicit. -->
    <ng-template #peekBody>
      @if (detailContent()) {
        <ng-container [ngTemplateOutlet]="detailContent()!" [ngTemplateOutletContext]="{ $implicit: selected() }" />
      }
    </ng-template>
  `,
  host: { class: 'hrm-list-screen' },
})
export class HrmListScreen {
  // Chrome
  readonly breadcrumb = input<HrmCrumb[]>([]);
  readonly title = input('');
  readonly subtitle = input('');
  readonly showBack = input(false);
  readonly back = output<void>();
  // Phân trang (two-way, tuỳ chọn — total=0 ẩn)
  readonly total = input(0);
  readonly pageIndex = model(1);
  readonly pageSize = model(10);
  readonly showSizeChanger = input(false);

  // Danh sách
  readonly columns = input<HrmGridColumn[]>([]);
  readonly data = input<Row[]>([]);
  readonly rowKey = input('id');
  readonly viewMode = model<HrmDataViewMode>('table');
  readonly viewModes = input<HrmDataViewMode[]>(['table', 'card']);
  readonly cardTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  readonly cardMin = input(260);
  readonly size = input<'small' | 'middle' | 'default'>('small');
  readonly selectable = input(false);
  readonly tableLabel = input('');
  readonly cardLabel = input('');

  // Chi tiết
  readonly detailContent = input<TemplateRef<{ $implicit: Row | null }> | null>(null);
  readonly detailModes = input<HrmPeekMode[]>(['side', 'center', 'full', 'tab']);
  /** Mode mở mặc định khi bấm 1 bản ghi. */
  readonly defaultMode = input<HrmPeekMode>('side');
  /** Trường lấy tiêu đề header chi tiết từ bản ghi. */
  readonly detailTitleField = input('name');
  /** Hàm sinh route bản ghi (cho mode full/tab). */
  readonly detailRoute = input<((row: Row) => string) | null>(null);
  readonly detailWidth = input(440);
  readonly detailModalWidth = input(680);
  readonly modeLabels = input<Partial<Record<HrmPeekMode, string>>>({});
  readonly switchLabel = input('');
  readonly expandLabel = input('');
  readonly closeLabel = input('');

  /** Phát khi mở 1 bản ghi (ngoài xử lý nội bộ). */
  readonly openRecord = output<Row>();

  protected readonly selected = signal<Row | null>(null);
  protected readonly peekOpen = signal(false);
  protected readonly peekMode = signal<HrmPeekMode>('side');

  protected readonly detailTitle = computed(() => {
    const r = this.selected();
    return r ? String(r[this.detailTitleField()] ?? '') : '';
  });
  protected readonly routeUrl = computed(() => {
    const fn = this.detailRoute();
    const r = this.selected();
    return fn && r ? fn(r) : '';
  });

  protected onOpen(row: Row): void {
    this.selected.set(row);
    this.peekMode.set(this.defaultMode());
    this.peekOpen.set(true);
    this.openRecord.emit(row);
  }
}
