import { Component, TemplateRef, computed, viewChild } from '@angular/core';
import {
  HrmListScreen, HrmGridColumn, HrmButton, HrmDataView,
  HrmUserCell, HrmStatusCell, HrmProgressCell, HrmTagsCell, HrmTag,
} from 'hrm-ui';
import { TablerIconComponent, IconSearch, IconPlus, IconFilter } from '@tabler/icons-angular';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';
import { SgEmployeeDetail } from './employee-detail';
import { EMPLOYEES, Employee, STATUS_META } from './_data';

/** Doc page · TEMPLATE "Màn hình Danh sách + Chi tiết" (nhóm Template).
 *  Dùng hrm-list-screen (drop-in như app-shell): điền columns/data + template thẻ/chi tiết
 *  là ra màn hình đầy đủ — danh sách Bảng/Thẻ, bấm bản ghi mở chi tiết đa-surface
 *  (Side/Center/Full/Tab). Đồng nghiệp prompt "màn hình danh sách" → dùng template này. */
@Component({
  selector: 'sg-doc-data-view',
  imports: [
    HrmListScreen, HrmDataView, HrmUserCell, HrmStatusCell, HrmProgressCell, HrmTagsCell, HrmTag,
    HrmButton, TablerIconComponent, SgEmployeeDetail,
    SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow,
  ],
  template: `
    <sg-doc category="Template" title="Màn hình Danh sách + Chi tiết"
      desc="Template sẵn dùng cho mọi màn hình danh sách dữ liệu: chrome (tiêu đề, toolbar, phân trang) + danh sách 2 chế độ Bảng/Thẻ + mở chi tiết đa-surface (cạnh bảng, giữa màn hình, toàn trang, tab mới). Điền dữ liệu là chạy.">

      <div sgOverview>
        <div class="tpl-frame">
          <hrm-list-screen
            title="Nhân sự" subtitle="Quản lý hồ sơ nhân viên toàn công ty"
            [breadcrumb]="crumbs" [columns]="columns()" [data]="$any(data)" rowKey="id"
            [cardTemplate]="$any(cardTpl())" [detailContent]="$any(detailTpl())"
            [detailRoute]="routeFor" detailTitleField="name"
            [total]="data.length" [pageSize]="8"
            tableLabel="Xem dạng bảng" cardLabel="Xem dạng thẻ"
            [modeLabels]="modeLabels" switchLabel="Đổi cách hiển thị" expandLabel="Mở toàn trang" closeLabel="Đóng">
            <span lsFilters class="tpl-search"><tabler-icon [icon]="icSearch" [size]="16" /><input placeholder="Tìm nhân viên…" /></span>
            <button lsActions type="button" class="tpl-btn-ghost"><tabler-icon [icon]="icFilter" [size]="16" /> Lọc</button>
            <hrm-button lsActions variant="primary" size="sm"><tabler-icon [icon]="icPlus" [size]="16" /> Thêm nhân viên</hrm-button>
          </hrm-list-screen>
        </div>
        <p style="font-size: var(--fs-13);color:var(--text-sub);margin:14px 0 0;max-width:66ch;line-height:1.55">
          Đây là <b>1 component</b> <code>hrm-list-screen</code> — điền <code>columns</code>, <code>data</code>
          và 2 template (thẻ · chi tiết) là ra màn hình đầy đủ. Bấm dòng/thẻ → mở <b>drawer cạnh bảng</b>;
          đổi sang giữa màn hình · toàn trang · tab mới ở đầu hộp chi tiết.
        </p>
      </div>

      <div sgUsage>
        <sg-use
          purpose="Template chuẩn cho MỌI màn hình danh sách dữ liệu (nhân sự, đơn từ, hợp đồng…). Dùng như app-shell: drop-in, điền dữ liệu, không dựng lại chrome/list/detail."
          [when]="when"
          behavior="hrm-list-screen ghép sẵn hrm-list-page (chrome) + hrm-data-view (Bảng/Thẻ) + hrm-detail-peek (4 surface). Tự quản bản ghi đang chọn + trạng thái mở."
          avoid="Màn hình không phải danh sách (dashboard, form nhập) — dùng recipe khác. Danh sách siêu đơn giản không cần chi tiết → chỉ hrm-grid." />
      </div>

      <div sgBest>
        <sg-do>Dùng <b>hrm-list-screen</b> làm điểm bắt đầu cho màn danh sách — không tự ghép lại list + detail.</sg-do>
        <sg-do>Đặt trong content của <b>hrm-app-shell</b> (side nav lấy từ shell, không lặp).</sg-do>
        <sg-do>Cấp <b>detailRoute</b> để bật mode Toàn trang / Tab mới (route bản ghi độc lập, chia sẻ link được).</sg-do>
        <sg-dont>Đừng nhồi logic riêng vào template — dữ liệu/columns/chi tiết truyền vào qua input/slot.</sg-dont>
      </div>

      <div sgExamples>
        <sg-example title="Chỉ Bảng — mở thẳng Toàn trang"
          desc="Ẩn chế độ Thẻ (viewModes chỉ table), mặc định mở chi tiết Toàn trang thay vì drawer. Hợp bản ghi nhiều trường cần không gian rộng.">
          <sg-row>
            <div class="tpl-frame">
              <hrm-list-screen
                title="Nhân sự" [columns]="columns()" [data]="$any(data.slice(0,4))" rowKey="id"
                [viewModes]="['table']" defaultMode="full" [detailContent]="$any(detailTpl())"
                [detailRoute]="routeFor" detailTitleField="name" [modeLabels]="modeLabels" />
            </div>
          </sg-row>
        </sg-example>

        <sg-example title="Toolbar tích hợp (search · sắp xếp · cột · xuất)"
          desc="hrm-data-view [toolbar]=true → thanh công cụ dùng chung trên MỌI chế độ xem: tìm kiếm lọc dữ liệu, Bộ lọc/Xuất phát event; nút Sắp xếp (đa cấp) + Cột chỉ hiện ở chế độ Bảng, nối chung state với bảng.">
          <div class="tpl-frame" style="padding:16px">
            <hrm-data-view [toolbar]="true" [modes]="['table','card']"
              [columns]="columns()" [data]="$any(data)" rowKey="id"
              [searchable]="true" [searchFields]="['name','email','role']" searchPlaceholder="Tìm theo tên hoặc email…"
              countLabel="nhân viên" [filterable]="true" [exportable]="true"
              [cardTemplate]="$any(cardTpl())" tableLabel="Bảng" cardLabel="Thẻ" />
          </div>
        </sg-example>
      </div>
    </sg-doc>

    <!-- Template thẻ (chế độ Thẻ) — context: row -->
    <ng-template #tplCard let-row>
      <div class="ec">
        <div class="ec-top">
          <hrm-user-cell [name]="row.name" [sub]="row.role" />
          <hrm-tag [color]="toneHue(row)" variant="light" [dot]="true" size="sm">{{ statusLabel(row) }}</hrm-tag>
        </div>
        <div class="ec-kpi">
          <span class="ec-kpi-l">KPI</span>
          <span class="ec-bar"><span class="ec-bar-f" [style.width.%]="row.kpi" [style.background]="kpiColor(row.kpi)"></span></span>
          <span class="ec-kpi-v">{{ row.kpi }}%</span>
        </div>
        <div class="ec-skills">
          @for (s of row.skills; track s) { <hrm-tag color="blue" variant="lighter" size="sm">{{ s }}</hrm-tag> }
        </div>
      </div>
    </ng-template>

    <!-- Cell Bảng -->
    <ng-template #cUser let-row><hrm-user-cell [name]="row.name" [sub]="row.email" /></ng-template>
    <ng-template #cSkills let-row><hrm-tags-cell [tags]="skillTags(row)" [max]="2" /></ng-template>
    <ng-template #cKpi let-row><hrm-progress-cell [value]="row.kpi" [color]="kpiTone(row.kpi)" /></ng-template>
    <ng-template #cStatus let-row><hrm-status-cell [status]="tone(row)" [label]="statusLabel(row)" variant="dot" /></ng-template>

    <!-- Nội dung chi tiết dùng chung mọi surface — row = bản ghi đang chọn -->
    <ng-template #tplDetail let-row><sg-employee-detail [emp]="row" /></ng-template>
  `,
  styles: [`
    .tpl-frame { padding: 16px; background: var(--bg-canvas); border: 1px solid var(--border-sub); border-radius: var(--radius-lg); }
    .tpl-search { display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); color: var(--text-sub); }
    .tpl-search input { border: 0; background: transparent; outline: none; font: inherit; font-size: var(--fs-13); color: var(--text-body); width: 160px; }
    .tpl-btn-ghost { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md); cursor: pointer; font: inherit; font-size: var(--fs-13); color: var(--text-body); }
    .tpl-btn-ghost:hover { border-color: var(--primary-border); }

    .ec { display: flex; flex-direction: column; gap: 12px; }
    .ec-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
    .ec-kpi { display: flex; align-items: center; gap: 8px; font-size: var(--fs-12); color: var(--text-sub); }
    .ec-kpi-l { flex: none; }
    .ec-bar { flex: 1; height: 6px; border-radius: var(--radius-full); background: var(--skeleton); overflow: hidden; }
    .ec-bar-f { display: block; height: 100%; border-radius: var(--radius-full); }
    .ec-kpi-v { flex: none; font-weight: 600; color: var(--text-strong); }
    .ec-skills { display: flex; flex-wrap: wrap; gap: 4px; }
  `],
})
export class SgDocDataView {
  protected readonly data = EMPLOYEES;
  protected readonly icSearch = IconSearch;
  protected readonly icPlus = IconPlus;
  protected readonly icFilter = IconFilter;

  protected readonly crumbs = [{ title: 'Nhân sự' }, { title: 'Danh sách' }];
  protected readonly modeLabels = {
    side: 'Cạnh bảng (drawer)', center: 'Giữa màn hình', full: 'Toàn trang', tab: 'Tab mới',
  };
  /** Route bản ghi cho mode Toàn trang / Tab mới. */
  protected readonly routeFor = (row: Record<string, unknown>): string =>
    `/styleguide/hrm/template/record?id=${row['id']}`;

  private readonly cUser = viewChild<TemplateRef<unknown>>('cUser');
  private readonly cSkills = viewChild<TemplateRef<unknown>>('cSkills');
  private readonly cKpi = viewChild<TemplateRef<unknown>>('cKpi');
  private readonly cStatus = viewChild<TemplateRef<unknown>>('cStatus');
  protected readonly cardTpl = viewChild<TemplateRef<unknown>>('tplCard');
  protected readonly detailTpl = viewChild<TemplateRef<unknown>>('tplDetail');

  protected readonly columns = computed<HrmGridColumn[]>(() => [
    { key: 'name', title: 'Nhân viên', cell: this.cUser() as never, width: '240px' },
    { key: 'dept', title: 'Phòng ban' },
    { key: 'skills', title: 'Kỹ năng', cell: this.cSkills() as never },
    { key: 'kpi', title: 'KPI', cell: this.cKpi() as never, width: '150px' },
    { key: 'status', title: 'Trạng thái', cell: this.cStatus() as never, width: '140px' },
  ]);

  protected tone(e: Employee): 'success' | 'warning' | 'neutral' { return STATUS_META[e.status].tone; }
  protected toneHue(e: Employee): 'green' | 'yellow' | 'gray' {
    return e.status === 'active' ? 'green' : e.status === 'leave' ? 'yellow' : 'gray';
  }
  protected statusLabel(e: Employee): string { return STATUS_META[e.status].label; }
  protected kpiColor(v: number): string {
    return v >= 80 ? 'var(--success-base)' : v >= 60 ? 'var(--warning-base)' : 'var(--error-base)';
  }
  protected kpiTone(v: number): 'green' | 'amber' | 'red' { return v >= 80 ? 'green' : v >= 60 ? 'amber' : 'red'; }
  protected skillTags(e: Employee): { label: string; color: string }[] {
    return e.skills.map((s) => ({ label: s, color: 'blue' }));
  }

  protected readonly when = [
    'Bất kỳ màn hình danh sách bản ghi nào (nhân sự, đơn từ, hợp đồng…)',
    'Cần xem chi tiết nhanh mà không rời danh sách',
    'Muốn cả bảng (quét cột) lẫn thẻ (trực quan) + mở chi tiết linh hoạt',
  ];
}
